namespace WildsEngine.Discoveries.Narratives
{ public sealed class DiscoveryNarrativeGroupRelationship:IDiscoveryNarrativeGroupRelationship { public DiscoveryNarrativeGroupRelationship(IDiscoveryNarrativeGroup left,IDiscoveryNarrativeGroup right,IReadOnlyList<IDiscoveryNarrativeCompositionDecision> decisions){Left=left??throw new ArgumentNullException(nameof(left));Right=right??throw new ArgumentNullException(nameof(right));if(ReferenceEquals(left,right))throw new ArgumentException("Distinct groups required.");if(decisions==null)throw new ArgumentNullException(nameof(decisions));var dc=new IDiscoveryNarrativeCompositionDecision[decisions.Count];var defs=new List<IDiscoveryNarrativeRelationshipDefinition>();var seen=new HashSet<Guid>();for(var i=0;i<dc.Length;i++){var d=decisions[i]??throw new ArgumentException("Decisions cannot contain null.");dc[i]=d;if(d.Relationship!=null&&seen.Add(d.Relationship.Id))defs.Add(d.Relationship);}Decisions=new ReadOnlyCollection<IDiscoveryNarrativeCompositionDecision>(dc);Definitions=new ReadOnlyCollection<IDiscoveryNarrativeRelationshipDefinition>(defs);}public IDiscoveryNarrativeGroup Left{get;}public IDiscoveryNarrativeGroup Right{get;}public IReadOnlyList<IDiscoveryNarrativeCompositionDecision> Decisions{get;}public IReadOnlyList<IDiscoveryNarrativeRelationshipDefinition> Definitions{get;} } }
